import java.util.Scanner;

public class Main {
    static final int MAXN = 200005;
    static final long INF = 1000000007L;

    static long a, b, c, bestA = -1, bestB = -1;
    static long X, Y, N;

    static void update(long a, int b) {
        if (a < 0) return;
        if (bestA == -1) {
            bestA = a;
            bestB = b;
            return;
        }
        long diffA = Math.abs(bestB * X - bestA * Y) * b;
        long diffB = Math.abs(b * X - a * Y) * bestB;
        if (diffA > diffB) {
            bestA = a;
            bestB = b;
        } else if (diffA == diffB && (b < bestB || (b == bestB && a < bestA))) {
            bestA = a;
            bestB = b;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        X = sc.nextLong();
        Y = sc.nextLong();
        N = sc.nextLong();

        for (int i = 1; i <= N; i++) {
            long val = i * X / Y;
            update(val - 1, i);
            update(val, i);
            update(val + 1, i);
        }
        System.out.println(bestA + "/" + bestB);
        sc.close();
    }
}
